/*
 * tstdi3.c - libc370 #187: the long long helpers, and (u)intptr_t, on MVS.
 *
 * cc370 compiles long long `*`, `/`, `%` and unary `-` into calls to
 * @@MULDI3, @@DIVDI3, @@MODDI3, @@UDIVDI, @@UMODDI and @@NEGDI2, which no
 * libc370 before #187 defined; and <stdint.h> had no uintptr_t for i370.
 * RED against the pre-#187 library, measured 2026-09-26: this file does
 * not compile (`uintptr_t' undeclared), and with case (5)
 * removed it does not link (ld370: @@MULDI3, @@DIVDI3, @@UDIVDI, @@MODDI3,
 * @@UMODDI, @@NEGDI2 unresolved).
 *
 * test/host/tstdi3.c checks the arithmetic against native 64-bit on about
 * 2 million operand pairs (12 million checks).  What only this run can
 * check is the S/370 code:
 * the word order of the union the helpers are built on, cc370's 32-bit
 * divide on the fast path, and that no 64-bit shape cc370 miscompiles
 * (cc370#467 signed divide by a constant, cc370#468 `<<` as SLDA) is
 * hiding in the helpers.  The same two defects bound this file: expected
 * values are written as word pairs and compared through a union, never
 * joined with `<<`, and every operand is loaded from a table so the
 * compiler cannot fold it or inline a divide by a constant.
 *
 *   (1) control: the word order the checks read is big-endian
 *   (2) known answers: 14 x 14 edge operands, every operation, values
 *       from Python's arbitrary-precision integers
 *   (3) identities on 3000 pseudo-random pairs of mixed width:
 *       q * b + r == a, |r| < |b|, r takes the dividend's sign
 *   (4) a zero divisor abends S0C9, like int / 0, for all four divides
 *   (5) uintptr_t / intptr_t: size, limits, and a pointer round trip
 *
 * Build:   make build
 *          cc370 -O1 -Iinclude -L build/sdk test/mvs/tstdi3.c \
 *                -o TSTDI3 -flinker-output=iebcopy
 *          ld370 --pack TSTDI3=TSTDI3.iebcopy -o tstdi3 -xmit \
 *                --dsn IBMUSER.LIBC370.DI3SCR
 *          -L build/sdk is not optional: without it the link takes the
 *          installed sysroot libc, which has none of the helpers, and
 *          ld370 says so.
 * Install: upload tstdi3.xmit to IBMUSER.MBT.XMIT.IN, jcl/recvdi3.jcl.
 * Run:     jcl/tstdi3.jcl.
 *
 * Run:     mvsdev JOB00449, CC 0000, 1138/1138, 2026-09-26; again after
 *          the red control below, JOB00453, same result.
 *
 * Proven red the same day against the three helper TUs with the union's
 * word order swapped (lo first - the layout a little-endian build takes),
 * linked ahead of the library: JOB00451, CC 0001, 787 of 1138 failed, all
 * in (2) and (3).  (1), (4) and (5) stay green there, as they should:
 * none of them goes through the helpers' union.
 *
 * RC: 0 = every check passed, 1 = a check failed (it is the COND CODE).
 */
#include <stdio.h>
#include <stdint.h>
#include <clibtry.h>

typedef long long           ll;
typedef unsigned long long  ull;

typedef union {
    ull u;
    ll  s;
    struct { unsigned hi, lo; } w;
} dw_t;

static int mbt_run = 0, mbt_passed = 0, mbt_failed = 0;

#define CHECK(cond, msg)                                                  \
    do {                                                                  \
        mbt_run++;                                                        \
        if (cond) { mbt_passed++; printf("  PASS: %s\n", (msg)); }         \
        else      { mbt_failed++; printf("  FAIL: %s\n", (msg)); }         \
    } while (0)

/* quiet variant for the bulk cases: only failures print, up to a limit */
static int quiet_failed = 0;

static void
expect(const char *what, int row, const dw_t *got, unsigned hi, unsigned lo)
{
    mbt_run++;
    if (got->w.hi == hi && got->w.lo == lo) { mbt_passed++; return; }
    mbt_failed++;
    if (++quiet_failed <= 20)
        printf("  FAIL: %s row %d = %08X %08X, want %08X %08X\n",
               what, row, got->w.hi, got->w.lo, hi, lo);
}

