#define NKAT ((int)(sizeof kat / sizeof kat[0]))

static void
load(dw_t *v, const unsigned *p)
{
    v->w.hi = p[0];
    v->w.lo = p[1];
}

/* 32-bit LCG, so the generator itself uses no 64-bit arithmetic */
static unsigned seed = 0x2545F491;

static unsigned
rnd(void)
{
    seed = seed * 1103515245u + 12345u;
    return seed;
}

/* mixed widths: half the pairs keep both high words zero or tiny, so the
   32-bit fast path and the 64-round loop are both exercised */
static void
operand(dw_t *v)
{
    unsigned hi = rnd(), lo = rnd();

    switch (rnd() & 7) {
    case 0: hi = 0; lo &= 0xFFFF; break;
    case 1: hi = 0; break;
    case 2: lo = 0; break;
    case 3: hi &= 0xFF; break;
    case 4: hi = 0xFFFFFFFF; break;            /* small negative */
    default: break;
    }
    v->w.hi = hi;
    v->w.lo = lo;
    if (hi == 0 && lo == 0)
        v->w.lo = 7;                            /* keep divisors non-zero */
}

static int
neg(const dw_t *v)
{
    return (v->w.hi & 0x80000000) != 0;
}

static ull
uabs(const dw_t *v)
{
    return neg(v) ? (ull)-v->s : v->u;
}

/* the zero-divisor cases; each should abend S0C9 inside try() */
static volatile ull zero_u;
static volatile ll  zero_s;
static volatile ull sink_u;
static volatile ll  sink_s;

static int zdiv_u(unsigned unused) { sink_u = sink_u / zero_u; return 0; }
static int zmod_u(unsigned unused) { sink_u = sink_u % zero_u; return 0; }
static int zdiv_s(unsigned unused) { sink_s = sink_s / zero_s; return 0; }
static int zmod_s(unsigned unused) { sink_s = sink_s % zero_s; return 0; }

int
main(void)
{
    dw_t a, b, r, q, m;
    int i, bad_id = 0, bad_mag = 0, bad_sign = 0;
    unsigned rc;
    char probe[4];
    char *pp;
    uintptr_t up;

    printf("=== TSTDI3: libc370 #187 long long helpers, (u)intptr_t ===\n\n");

    printf("(1) control - the checks read the words big-endian\n");
    a.w.hi = 0x01234567;
    a.w.lo = 0x89ABCDEF;
    CHECK(sizeof(ll) == 8, "(1) long long is 8 bytes");
    CHECK(((unsigned char *)&a)[0] == 0x01 && ((unsigned char *)&a)[7] == 0xEF,
          "(1) hi word first in storage");
    CHECK((unsigned)(a.u >> 32) == 0x01234567,
          "(1) >> 32 of the union agrees with its hi word");

    printf("(2) known answers, %d operand pairs\n", NKAT);
    for (i = 0; i < NKAT; i++) {
        load(&a, &kat[i][0]);
        load(&b, &kat[i][2]);
        r.s = a.s * b.s;   expect("a*b",      i, &r, kat[i][4],  kat[i][5]);
        r.s = -a.s;        expect("-a",       i, &r, kat[i][6],  kat[i][7]);
        if (b.w.hi == 0 && b.w.lo == 0)
            continue;
        r.u = a.u / b.u;   expect("a/b (u)",  i, &r, kat[i][8],  kat[i][9]);
        r.u = a.u % b.u;   expect("a%b (u)",  i, &r, kat[i][10], kat[i][11]);
        r.s = a.s / b.s;   expect("a/b (s)",  i, &r, kat[i][12], kat[i][13]);
        r.s = a.s % b.s;   expect("a%b (s)",  i, &r, kat[i][14], kat[i][15]);
    }
    CHECK(quiet_failed == 0, "(2) every known answer matches");

    printf("(3) identities, 3000 pseudo-random pairs\n");
    for (i = 0; i < 3000; i++) {
        operand(&a);
        operand(&b);

        q.u = a.u / b.u;
        m.u = a.u % b.u;
        r.u = q.u * b.u + m.u;
        if (r.u != a.u) bad_id++;
        if (!(m.u < b.u)) bad_mag++;

        q.s = a.s / b.s;
        m.s = a.s % b.s;
        r.s = q.s * b.s + m.s;
        if (r.u != a.u) bad_id++;
        if (!(uabs(&m) < uabs(&b))) bad_mag++;
        if (m.u != 0 && neg(&m) != neg(&a)) bad_sign++;
    }
    printf("  identity %d, magnitude %d, sign %d failures\n",
           bad_id, bad_mag, bad_sign);
    CHECK(bad_id == 0,   "(3) q * b + r == a, unsigned and signed");
    CHECK(bad_mag == 0,  "(3) |r| < |b|");
    CHECK(bad_sign == 0, "(3) r takes the sign of the dividend");

    printf("(4) a zero divisor abends S0C9\n");
    sink_u = 1;
    sink_s = 1;
    rc = (unsigned)try(zdiv_u, 0);
    printf("  unsigned /: %06X\n", rc);
    CHECK(rc == 0x0C9000, "(4) unsigned / 0 is S0C9");
    rc = (unsigned)try(zmod_u, 0);
    printf("  unsigned %%: %06X\n", rc);
    CHECK(rc == 0x0C9000, "(4) unsigned % 0 is S0C9");
    rc = (unsigned)try(zdiv_s, 0);
    printf("  signed /:   %06X\n", rc);
    CHECK(rc == 0x0C9000, "(4) signed / 0 is S0C9");
    rc = (unsigned)try(zmod_s, 0);
    printf("  signed %%:   %06X\n", rc);
    CHECK(rc == 0x0C9000, "(4) signed % 0 is S0C9");

    printf("(5) uintptr_t / intptr_t\n");
    pp = &probe[1];
    up = (uintptr_t)pp;
    CHECK(sizeof(uintptr_t) == sizeof(char *), "(5) uintptr_t holds a pointer");
    CHECK(sizeof(intptr_t) == sizeof(char *), "(5) intptr_t holds a pointer");
    CHECK((char *)up == pp, "(5) pointer -> uintptr_t -> pointer");
    CHECK((char *)(up + 1) == pp + 1, "(5) uintptr_t arithmetic is bytes");
    CHECK(UINTPTR_MAX == 0xFFFFFFFFu, "(5) UINTPTR_MAX");
    CHECK(INTPTR_MAX == 0x7FFFFFFF && INTPTR_MIN < 0, "(5) INTPTR_MAX/MIN");
    CHECK(PTRDIFF_MAX == INTPTR_MAX, "(5) PTRDIFF_MAX");

    printf("\n=== %d run, %d passed, %d failed ===\n",
           mbt_run, mbt_passed, mbt_failed);
    return mbt_failed ? 1 : 0;
}
